class Solution:
    def countDominant(self, root: Optional[TreeNode]) -> int:
        self.ans = 0
        def dfs(node):
            if not node:
                return float('-inf')
            m = max(node.val, dfs(node.left), dfs(node.right))
            if m == node.val:
                self.ans += 1
            return m
        dfs(root)
        return self.ans

