class Solution {
    private int ans = 0;
    private int dfs(TreeNode node) {
        if (node == null) return Integer.MIN_VALUE;
        int m = node.val;
        if (node.left != null) m = Math.max(m, dfs(node.left));
        if (node.right != null) m = Math.max(m, dfs(node.right));
        if (m == node.val) ans++;
        return m;
    }
    public int countDominant(TreeNode root) {
        dfs(root);
        return ans;
    }
}

