class Solution {
public:
    int countDominant(TreeNode* root) {
        int ans = 0;
        unordered_map<TreeNode*, int> mx;
        vector<pair<TreeNode*, bool>> st{{root, false}};
        while (!st.empty()) {
            auto [node, done] = st.back(); st.pop_back();
            if (done) {
                int m = node->val;
                if (node->left && mx[node->left] > m) m = mx[node->left];
                if (node->right && mx[node->right] > m) m = mx[node->right];
                mx[node] = m;
                if (m == node->val) ans++;
            } else {
                st.push_back({node, true});
                if (node->left) st.push_back({node->left, false});
                if (node->right) st.push_back({node->right, false});
            }
        }
        return ans;
    }
};

