class Solution {
    public int countDominant(TreeNode root) {
        int ans = 0;
        Map<TreeNode, Integer> mx = new HashMap<>();
        Deque<Object[]> st = new ArrayDeque<>();
        st.push(new Object[]{root, false});
        while (!st.isEmpty()) {
            Object[] top = st.pop();
            TreeNode node = (TreeNode) top[0];
            boolean done = (Boolean) top[1];
            if (done) {
                int m = node.val;
                if (node.left != null && mx.get(node.left) > m) m = mx.get(node.left);
                if (node.right != null && mx.get(node.right) > m) m = mx.get(node.right);
                mx.put(node, m);
                if (m == node.val) ans++;
            } else {
                st.push(new Object[]{node, true});
                if (node.left != null) st.push(new Object[]{node.left, false});
                if (node.right != null) st.push(new Object[]{node.right, false});
            }
        }
        return ans;
    }
}

